  "columns": "<div class=\"t-columns t-columns--{{count}} t-columns--{{widths}} t-columns--{{align}}\">\n  <div class=\"t-column\" data-slot=\"first\"></div>\n  <div class=\"t-column\" data-slot=\"second\"></div>\n  <div class=\"t-column\" data-slot=\"third\"></div>\n</div>\n",
