  "dialogue": "<section class=\"t-dialogue t-dialogue--{{style}}\" data-t-group aria-label=\"{{title}}\">\n  <div class=\"t-dialogue-stage\" data-if=\"style == scene\" data-t-stage></div>\n  <div class=\"t-dialogue-log\" data-t-log></div>\n  <div class=\"t-dialogue-start\" data-if=\"begins == click\"><button type=\"button\" class=\"t-btn t-btn--primary t-dialogue-start-btn\" data-t-start></button></div>\n  <div class=\"t-dialogue-options\" data-t-options></div>\n  <div class=\"t-dialogue-debrief\" data-if=\"debrief\" data-t-debrief hidden></div>\n</section>\n",
  "divider": "<!-- Decoration: only a line is read, as a separator. The number is a counter of the screen (CSS). -->\n<hr class=\"t-divider t-divider--line t-divider--{{size}}\" data-if=\"presentation == line\">\n<div class=\"t-divider t-divider--{{presentation}} t-divider--{{size}}\" data-if=\"presentation != line\" data-restart=\"{{restart}}\" aria-hidden=\"true\">\n  <span class=\"t-divider-ornament\" data-if=\"presentation == ornament\"></span>\n  <span class=\"t-divider-number\" data-if=\"presentation == number\"></span>\n</div>\n",
