  "gallery": "<!-- zoom: each image is a button that opens it in the player's lightbox, with its caption, and previous\n     and next between the images of the gallery. -->\n<figure class=\"t-gallery t-gallery--{{presentation}}\" data-if=\"presentation == grid\" data-columns=\"{{columns}}\" data-ratio=\"{{ratio}}\">\n  <ul class=\"t-gallery-list\" role=\"list\">\n    <li class=\"t-gallery-item\" data-each=\"images\">\n      <figure class=\"t-figure\" style=\"--focus-x: {{focus.x}}; --focus-y: {{focus.y}}\">\n        <span class=\"t-media\" data-if=\"!zoom\">\n          <img data-if=\"decorative\" src=\"{{asset}}\" alt=\"\" loading=\"lazy\" decoding=\"async\">\n          <img data-if=\"!decorative\" src=\"{{asset}}\" alt=\"{{alt}}\" loading=\"lazy\" decoding=\"async\">\n        </span>\n        <button class=\"t-zoom\" data-if=\"zoom\" data-t-zoom>\n          <img data-if=\"decorative\" src=\"{{asset}}\" alt=\"\" loading=\"lazy\" decoding=\"async\">\n          <img data-if=\"!decorative\" src=\"{{asset}}\" alt=\"{{alt}}\" loading=\"lazy\" decoding=\"async\">\n        </button>\n        <figcaption data-if=\"caption\" data-t-caption>{{caption}}</figcaption>\n      </figure>\n    </li>\n  </ul>\n  <p class=\"t-genmark\" data-if=\"generated\" data-t-label=\"generated\"></p>\n  <figcaption class=\"t-gallery-caption\" data-if=\"caption\">{{caption}}</figcaption>\n</figure>\n<figure class=\"t-gallery t-gallery--{{presentation}}\" data-if=\"presentation == mosaic\" data-columns=\"{{columns}}\">\n  <ul class=\"t-gallery-list\" role=\"list\">\n    <li class=\"t-gallery-item\" data-each=\"images\">\n      <figure class=\"t-figure\">\n        <span class=\"t-media\" data-if=\"!zoom\">\n          <img data-if=\"decorative\" src=\"{{asset}}\" alt=\"\" loading=\"lazy\" decoding=\"async\">\n          <img data-if=\"!decorative\" src=\"{{asset}}\" alt=\"{{alt}}\" loading=\"lazy\" decoding=\"async\">\n        </span>\n        <button class=\"t-zoom\" data-if=\"zoom\" data-t-zoom>\n          <img data-if=\"decorative\" src=\"{{asset}}\" alt=\"\" loading=\"lazy\" decoding=\"async\">\n          <img data-if=\"!decorative\" src=\"{{asset}}\" alt=\"{{alt}}\" loading=\"lazy\" decoding=\"async\">\n        </button>\n        <figcaption data-if=\"caption\" data-t-caption>{{caption}}</figcaption>\n      </figure>\n    </li>\n  </ul>\n  <p class=\"t-genmark\" data-if=\"generated\" data-t-label=\"generated\"></p>\n  <figcaption class=\"t-gallery-caption\" data-if=\"caption\">{{caption}}</figcaption>\n</figure>\n<!-- carousel: one image at a time with its caption (a sequence: the room of the tallest is kept),\n     Previous and Next, a thumbnail per image (wide containers) and where the learner is. -->\n<figure class=\"t-gallery t-gallery--carousel\" data-if=\"presentation == carousel\" data-ratio=\"{{ratio}}\">\n  <div class=\"t-gallery-carousel\" data-t-sequence>\n    <div class=\"t-gallery-slides\">\n      <figure class=\"t-gallery-slide t-figure\" data-each=\"images\" data-t-item=\"{{id}}\">\n        <span class=\"t-media\" data-if=\"!zoom\">\n          <img data-if=\"decorative\" src=\"{{asset}}\" alt=\"\" loading=\"lazy\" decoding=\"async\">\n          <img data-if=\"!decorative\" src=\"{{asset}}\" alt=\"{{alt}}\" loading=\"lazy\" decoding=\"async\">\n        </span>\n        <button class=\"t-zoom\" data-if=\"zoom\" data-t-zoom>\n          <img data-if=\"decorative\" src=\"{{asset}}\" alt=\"\" loading=\"lazy\" decoding=\"async\">\n          <img data-if=\"!decorative\" src=\"{{asset}}\" alt=\"{{alt}}\" loading=\"lazy\" decoding=\"async\">\n        </button>\n        <figcaption data-if=\"caption\" data-t-caption>{{caption}}</figcaption>\n      </figure>\n    </div>\n    <div class=\"t-gallery-nav\">\n      <button class=\"t-gallery-arrow\" data-t-prev><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M14.5 6l-6 6 6 6\"/></svg></button>\n      <ol class=\"t-gallery-thumbs\">\n        <li data-each=\"images\"><button class=\"t-gallery-thumb\" data-t-goto=\"{{id}}\" style=\"--focus-x: {{focus.x}}; --focus-y: {{focus.y}}\"><img src=\"{{asset}}\" alt=\"\" loading=\"lazy\" decoding=\"async\"></button></li>\n      </ol>\n      <span class=\"t-gallery-position\" data-t-position></span>\n      <button class=\"t-gallery-arrow\" data-t-next><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M9.5 6l6 6-6 6\"/></svg></button>\n    </div>\n  </div>\n  <p class=\"t-genmark\" data-if=\"generated\" data-t-label=\"generated\"></p>\n  <figcaption class=\"t-gallery-caption\" data-if=\"caption\">{{caption}}</figcaption>\n</figure>\n<figure class=\"t-gallery t-gallery--compare\" data-if=\"presentation == compare\">\n  <div class=\"t-compare\" data-t-compare>\n    <div class=\"t-compare-side t-compare-before\" data-each=\"images\" data-if=\"@first\" style=\"--focus-x: {{focus.x}}; --focus-y: {{focus.y}}\">\n      <img data-if=\"decorative\" src=\"{{asset}}\" alt=\"\" loading=\"lazy\" decoding=\"async\">\n      <img data-if=\"!decorative\" src=\"{{asset}}\" alt=\"{{alt}}\" loading=\"lazy\" decoding=\"async\">\n      <p class=\"t-compare-label\" data-t-compare-label data-if=\"caption\">{{caption}}</p>\n    </div>\n    <div class=\"t-compare-side t-compare-after\" data-each=\"images\" data-if=\"@last\" style=\"--focus-x: {{focus.x}}; --focus-y: {{focus.y}}\">\n      <img data-if=\"decorative\" src=\"{{asset}}\" alt=\"\" loading=\"lazy\" decoding=\"async\">\n      <img data-if=\"!decorative\" src=\"{{asset}}\" alt=\"{{alt}}\" loading=\"lazy\" decoding=\"async\">\n      <p class=\"t-compare-label\" data-t-compare-label data-if=\"caption\">{{caption}}</p>\n    </div>\n  </div>\n  <p class=\"t-genmark\" data-if=\"generated\" data-t-label=\"generated\"></p>\n  <figcaption class=\"t-gallery-caption\" data-if=\"caption\">{{caption}}</figcaption>\n</figure>\n",
